def seed_years(apps, schema_editor):
    """Give every existing company the years from the one its books begin in
    up to the one holding today."""
    from datetime import date

    from core.fiscal import add_months, month_end, year_name
    from core.models import fiscal_year_start

    Company = apps.get_model("core", "Company")
    FiscalYear = apps.get_model("core", "FiscalYear")
    FiscalPeriod = apps.get_model("core", "FiscalPeriod")
    today = date.today()
    for company in Company.objects.all():
        month = company.fiscal_year_start_month
        start = fiscal_year_start(company.books_start, month)
        last = fiscal_year_start(today, month)
        while start <= last:
            end = month_end(add_months(start, 11))
            year = FiscalYear.objects.create(
                company=company, name=year_name(start, end), start_date=start, end_date=end
            )
            day = start
            while day <= end:
                FiscalPeriod.objects.create(year=year, start_date=day, end_date=month_end(day))
                day = add_months(day, 1)
            start = add_months(start, 12)


